  function buildSiteChecklist(d){
    let n = 0, s = 1; const used = {};
    const uid = (base) => { let id = base.replace(/[^A-Za-z0-9_]/g,'_'); if (used[id]) id += '_' + (++used[id]); else used[id] = 1; return id; };
    const sections = [ plainSafety(d.prefix, 'Section 1 — Pre-Job Safety, Isolation & Preparation', d.safety) ];
    d.sections.forEach(sec => {
      s++;
      sections.push({ id: uid(d.prefix+'_'+sec.key), title: 'Section '+s+' — '+sec.title,
        items: sec.rows.map((r, i) => {
          const it = checklistPoint(uid(d.prefix+'_'+(r[4] || (sec.key+'_'+(i+1)))), String(++n), r[0], r[1], r[2], r[3]);
          if (!r[0]) it.label = r[1];
          return it;
        }) });
    });
    return { id: d.id, title: d.title, dept: d.dept, category: d.category, tagPlaceholder: d.tag,
      defaultVisual: true, defaultVibration: d.category === 'genset', sections };
  }
  const SITE_CHECKLISTS = SITE_CHECKLIST_DATA.map(buildSiteChecklist);

  // Gen Set: site Hyundai PM package first, then the generic fire-risk and standby checklists
  SITE_CHECKLISTS.filter(c => c.category === 'genset').forEach(c => EQUIPMENT.push(c));
  EQUIPMENT.push(gensetTurboFire(), gensetStandby());
  // Mobile Crusher: MCR001 PM route checklists
  SITE_CHECKLISTS.filter(c => c.category === 'mcrusher').forEach(c => EQUIPMENT.push(c));
  hmeFleet().forEach(e => EQUIPMENT.push(e));

